import { ref } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';
import DockerContainers from "@/components/Container/DockerContainers.vue"; // 你之前写的容器列表组件，暴露 selected 容器名

export default {
  __name: 'ViewFirewallRulesDialog',
  setup(__props, {
    expose: __expose
  }) {
    const visible = ref(false);
    const containerName = ref('');
    const chain = ref('INPUT');
    const rules = ref([]);
    const loading = ref(false);

    // 暴露方法供父组件调用
    const openDialog = () => {
      visible.value = true;
    };
    __expose({
      openDialog
    });

    // 查看规则逻辑
    const handleViewRules = async () => {
      if (!containerName.value) {
        ElMessage.warning('请选择容器');
        return;
      }
      loading.value = true;
      try {
        const response = await axios.get('http://localhost:8081/firewall/list', {
          params: {
            containerName: containerName.value,
            chain: chain.value
          }
        });
        const lines = response.data.split('\n').filter(line => line.trim() !== '');
        rules.value = lines.map((line, index) => ({
          index: index + 1,
          content: line
        }));
      } catch (err) {
        ElMessage.error(`获取规则失败：${err?.response?.data || err.message}`);
      } finally {
        loading.value = false;
      }
    };
    const __returned__ = {
      visible,
      containerName,
      chain,
      rules,
      loading,
      openDialog,
      handleViewRules,
      ref,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      DockerContainers
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
